// Radial disc cam + in-line translating roller follower + compression return spring.
// World mm, z up. Cam plane x-z at y∈CAM_Y, shaft axis along y at z=ZC. Follower axis x=0,y=16.
// Cam turns by phi (rad, CCW in x-z). Follower angle in cam frame = phi. Pitch radius Rb+Rr+s(phi).
// Idealized: rigid parts, no friction/backlash; spring force is a linear k·compression estimate.
export const D = {
  Rb: 28, Rr: 7, ZC: 72, CAM_Y: [12, 20], ROLL_Y: [10, 22], CHEEK: [[7, 9], [23, 25]],
  shaftR: 6, shaftY: [-60, 26], plateY: [-6, 4], pedY: [-54, -42], baseZ: 8,
  armZ: [196, 210], armY: [4, 28], FY: 16, collarOff: 30, collarH: 4,
  stemTop: 118, k: 0.4, L0: 70, liftMin: 6, liftMax: 40, maxPressure: 30,
  phases: [120, 60, 120, 60]
};
export const LAWS = { cycloidal: 'Cycloidal', harmonic: 'Harmonic', poly345: '3-4-5 polynomial' };
const TAU = Math.PI * 2;
function unit(law, u) { // normalized rise 0..1 -> [y, dy/du, d2y/du2]
  if (law === 'harmonic') return [(1 - Math.cos(Math.PI * u)) / 2, Math.PI / 2 * Math.sin(Math.PI * u), Math.PI ** 2 / 2 * Math.cos(Math.PI * u)];
  if (law === 'poly345') return [10 * u ** 3 - 15 * u ** 4 + 6 * u ** 5, 30 * u ** 2 - 60 * u ** 3 + 30 * u ** 4, 60 * u - 180 * u ** 2 + 120 * u ** 3];
  return [u - Math.sin(TAU * u) / TAU, 1 - Math.cos(TAU * u), TAU * Math.sin(TAU * u)];
}
export function phaseOf(deg) {
  const d = ((deg % 360) + 360) % 360, [a, b, c] = D.phases;
  return d < a ? 'Rise' : d < a + b ? 'Dwell (top)' : d < a + b + c ? 'Return' : 'Dwell (bottom)';
}
// displacement s (mm), ds/dphi (mm/rad), d2s/dphi2 (mm/rad^2)
export function law(lawName, h, phi) {
  const deg = ((phi * 180 / Math.PI) % 360 + 360) % 360, [a, b, c] = D.phases;
  const R = (x) => x * Math.PI / 180;
  if (deg < a) { const [y, dy, ddy] = unit(lawName, deg / a); return [h * y, h * dy / R(a), h * ddy / R(a) ** 2]; }
  if (deg < a + b) return [h, 0, 0];
  if (deg < a + b + c) { const [y, dy, ddy] = unit(lawName, (deg - a - b) / c); return [h * (1 - y), -h * dy / R(c), -h * ddy / R(c) ** 2]; }
  return [0, 0, 0];
}
const pitchAt = (L, h, t) => { const r = D.Rb + D.Rr + law(L, h, t)[0]; return [r * Math.sin(t), r * Math.cos(t)]; };
// Cam working profile in the cam frame (pitch curve offset inward by Rr).
export function profile(L, h, n = 240) {
  const pts = [], e = 1e-4;
  for (let i = 0; i < n; i++) {
    const t = (i / n) * TAU, p = pitchAt(L, h, t), a = pitchAt(L, h, t - e), b = pitchAt(L, h, t + e);
    const tx = b[0] - a[0], tz = b[1] - a[1], m = Math.hypot(tx, tz);
    // curve runs clockwise in (x,z) as t grows; outward normal = (-tz, tx)/m
    pts.push([p[0] - D.Rr * (-tz / m), p[1] - D.Rr * (tx / m)]);
  }
  return pts;
}
export const rot = ([x, z], phi) => [x * Math.cos(phi) - z * Math.sin(phi), x * Math.sin(phi) + z * Math.cos(phi)];
export function pressureAngle(L, h, phi) { const [s, v] = law(L, h, phi); return Math.atan2(Math.abs(v), D.Rb + D.Rr + s) * 180 / Math.PI; }
export function maxPressure(L, h) { let m = 0; for (let i = 0; i < 720; i++) m = Math.max(m, pressureAngle(L, h, i / 720 * TAU)); return m; }
export function initial() { return { phi: 0, law: 'cycloidal', lift: 16, rpm: 20, playing: false, rollAngle: 0, msg: 'Ready' }; }
export function pose(st) {
  const [s, v, acc] = law(st.law, st.lift, st.phi);
  const zr = D.ZC + D.Rb + D.Rr + s, collarTop = zr + D.collarOff + D.collarH;
  const springL = D.armZ[0] - collarTop;
  return { s, v, acc, zr, roller: [0, D.FY, zr], collarTop, springL, springF: D.k * (D.L0 - springL),
    pressure: pressureAngle(st.law, st.lift, st.phi), phase: phaseOf(st.phi * 180 / Math.PI),
    stemTop: zr + D.stemTop, deg: ((st.phi * 180 / Math.PI) % 360 + 360) % 360 };
}
// Pure rolling: roller spin follows the cam-relative pitch arc length.
function rollStep(st, dphi) { const a = pitchAt(st.law, st.lift, st.phi), b = pitchAt(st.law, st.lift, st.phi + dphi); return -Math.sign(dphi) * Math.hypot(b[0] - a[0], b[1] - a[1]) / D.Rr; }
export function advance(st, dt) {
  if (!st.playing) return st;
  const dphi = Math.min(dt, 0.1) * st.rpm / 60 * TAU;
  return { ...st, phi: (st.phi + dphi) % TAU, rollAngle: st.rollAngle + rollStep(st, dphi) };
}
export function setAngle(st, deg) { const phi = (((+deg) % 360) + 360) % 360 * Math.PI / 180; return { ...st, phi, rollAngle: st.rollAngle + rollStep(st, phi - st.phi) }; }
export const setRpm = (st, r) => ({ ...st, rpm: Math.max(2, Math.min(60, +r || 20)) });
export const togglePlay = (st) => ({ ...st, playing: !st.playing, msg: st.playing ? 'Paused' : 'Running' });
export function setLaw(st, L) { if (!LAWS[L]) return st; const m = maxPressure(L, st.lift); if (m > D.maxPressure) return { ...st, msg: `Blocked: ${LAWS[L]} would reach ${m.toFixed(1)}° pressure angle` }; return { ...st, law: L, msg: `Law: ${LAWS[L]}` }; }
export function setLift(st, h) {
  h = +h; if (!(h >= D.liftMin && h <= D.liftMax)) return { ...st, msg: `Blocked: lift must be ${D.liftMin}–${D.liftMax} mm` };
  const m = maxPressure(st.law, h);
  if (m > D.maxPressure) return { ...st, msg: `Blocked: pressure angle ${m.toFixed(1)}° > ${D.maxPressure}° limit` };
  if (D.armZ[0] - (D.ZC + D.Rb + D.Rr + h + D.collarOff + D.collarH) < 24) return { ...st, msg: 'Blocked: spring would go solid' };
  return { ...st, lift: h, msg: `Lift set to ${h} mm` };
}

