import * as M from './model.mjs';
const { D } = M;
function segDist(p, a, b) { const dx = b[0] - a[0], dz = b[1] - a[1], t = Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dz) / (dx * dx + dz * dz))); return Math.hypot(p[0] - a[0] - t * dx, p[1] - a[1] - t * dz); }
function inside(p, poly) { let c = false; for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) { const a = poly[i], b = poly[j]; if ((a[1] > p[1]) !== (b[1] > p[1]) && p[0] < (b[0] - a[0]) * (p[1] - a[1]) / (b[1] - a[1]) + a[0]) c = !c; } return c; }
function contactErr(L, h, n) {
  const prof = M.profile(L, h, 720); let worst = 0, at = 0, pen = false;
  for (let i = 0; i < n; i++) {
    const phi = i / n * Math.PI * 2, st = { ...M.initial(), law: L, lift: h, phi }, p = M.pose(st);
    const w = prof.map((q) => M.rot(q, phi)), c = [0, p.zr - D.ZC];
    let d = 1e9; for (let j = 0; j < w.length; j++) d = Math.min(d, segDist(c, w[j], w[(j + 1) % w.length]));
    if (inside(c, w)) pen = true;
    if (Math.abs(d - D.Rr) > worst) { worst = Math.abs(d - D.Rr); at = i / n * 360; }
  }
  return { worst, at, pen };
}
export function verify() {
  const out = [], add = (name, passed, detail = '') => out.push({ name, passed: !!passed, detail });
  for (const L of Object.keys(M.LAWS)) { const r = contactErr(L, 16, 144); add(`roller touches cam profile (${L})`, r.worst < 0.25 && !r.pen, `max gap error ${r.worst.toFixed(3)} mm at ${r.at}°`); }
  const r2 = contactErr('cycloidal', 28, 144); add('contact holds at large lift', r2.worst < 0.3 && !r2.pen, `err ${r2.worst.toFixed(3)}`);
  let st = { ...M.initial(), playing: true }, seen = new Set(), sMin = 1e9, sMax = -1e9, jump = 0, prev = M.pose(st).s;
  for (let i = 0; i < 1800; i++) { st = M.advance(st, 1 / 60); const p = M.pose(st); seen.add(p.phase); sMin = Math.min(sMin, p.s); sMax = Math.max(sMax, p.s); jump = Math.max(jump, Math.abs(p.s - prev)); prev = p.s; }
  add('one revolution visits rise, dwell, return, dwell', seen.size === 4, [...seen].join(','));
  add('travel spans exactly 0..lift', Math.abs(sMin) < 0.05 && Math.abs(sMax - 16) < 0.05, `${sMin.toFixed(2)}..${sMax.toFixed(2)}`);
  add('displacement continuous (no step)', jump < 0.6, `max step ${jump.toFixed(3)} mm`);
  let vj = 0; for (let d = 0; d < 360; d += 0.5) { const a = M.law('cycloidal', 16, d * Math.PI / 180), b = M.law('cycloidal', 16, (d + 0.5) * Math.PI / 180); vj = Math.max(vj, Math.abs(b[1] - a[1])); }
  add('cycloidal velocity continuous across phase joints', vj < 0.5, `max dv ${vj.toFixed(3)}`);
  const dw = M.law('poly345', 16, 150 * Math.PI / 180); add('top dwell holds follower still', dw[0] === 16 && dw[1] === 0);
  let springOk = true, stemOk = true, minEng = 1e9;
  for (let d = 0; d < 360; d += 2) { const p = M.pose(M.setAngle({ ...M.initial(), lift: 31 }, d)); if (!(p.springL < D.L0 && p.springL >= 24 && p.springF > 0)) springOk = false; const eng = Math.min(p.stemTop, D.armZ[1]) - D.armZ[0]; minEng = Math.min(minEng, eng); if (eng < 12) stemOk = false; }
  add('spring stays preloaded and above solid length', springOk);
  add('stem engaged in guide bushing whole stroke', stemOk, `min ${minEng.toFixed(1)} mm`);
  const ov = Math.min(D.CAM_Y[1], D.ROLL_Y[1]) - Math.max(D.CAM_Y[0], D.ROLL_Y[0]);
  add('roller face overlaps cam width axially', ov >= 6, `${ov} mm`);
  add('fork cheeks clear the cam plate', D.CHEEK[0][1] < D.CAM_Y[0] && D.CHEEK[1][0] > D.CAM_Y[1]);
  let lo = 1e9; for (const q of M.profile('cycloidal', 31, 360)) lo = Math.min(lo, D.ZC - Math.hypot(q[0], q[1]));
  add('cam clears the base plate', D.ZC - (D.Rb + 31) > D.baseZ + 4);
  const b1 = M.setLift(M.initial(), 40); add('excessive lift is blocked', b1.lift === 16 && /Blocked/.test(b1.msg), b1.msg);
  const ok = M.setLift(M.initial(), 24); add('valid lift accepted', ok.lift === 24 && M.maxPressure('cycloidal', 24) <= D.maxPressure);
  const p1 = M.togglePlay(M.initial()), p2 = M.advance(p1, 0.5), p3 = M.togglePlay(p2), p4 = M.advance(p3, 0.5);
  add('pause stops cam rotation', p2.phi > 0 && p4.phi === p2.phi);
  const fast = M.advance(M.setRpm(p1, 40), 0.25), slow = M.advance(M.setRpm(p1, 10), 0.25);
  add('speed scales angular advance', Math.abs(fast.phi / slow.phi - 4) < 1e-6);
  return out;
}

