import * as k from '/kit/iso-kit.mjs';
import * as M from './model.mjs';
import { draw, worldBounds, contactPoint } from './geometry.mjs';

const CW = 300, CH = 120;
function chart(st) {
  const h = Math.max(st.lift, 1), X = (d) => 30 + d / 360 * (CW - 40), Y = (s) => CH - 22 - s / M.D.liftMax * (CH - 40);
  let pS = '', pV = '', vmax = 1e-9;
  for (let d = 0; d <= 360; d += 2) vmax = Math.max(vmax, Math.abs(M.law(st.law, st.lift, d * Math.PI / 180)[1]));
  for (let d = 0; d <= 360; d += 2) { const [s, v] = M.law(st.law, st.lift, d * Math.PI / 180); pS += (d ? 'L' : 'M') + X(d).toFixed(1) + ' ' + Y(s).toFixed(1); pV += (d ? 'L' : 'M') + X(d).toFixed(1) + ' ' + (CH - 22 - (CH - 40) / 2 - v / vmax * (CH - 46) / 2).toFixed(1); }
  let acc = 0, bands = '';
  const names = ['Rise', 'Dwell', 'Return', 'Dwell'];
  M.D.phases.forEach((w, i) => { bands += `<rect class="band b${i % 2}" x="${X(acc)}" y="8" width="${X(acc + w) - X(acc)}" height="${CH - 30}"/><text class="ct" x="${X(acc + w / 2)}" y="${CH - 8}" text-anchor="middle">${names[i]}</text>`; acc += w; });
  const p = M.pose(st), cx = X(p.deg);
  return `<svg viewBox="0 0 ${CW} ${CH}" class="lawchart" role="img" aria-label="Displacement law s(θ)">${bands}
<line class="axis" x1="30" y1="${CH - 22}" x2="${CW - 10}" y2="${CH - 22}"/><line class="axis" x1="30" y1="8" x2="30" y2="${CH - 22}"/>
<text class="ct" x="4" y="${Y(h) + 3}">${h}</text><text class="ct" x="4" y="${CH - 19}">0</text>
<path class="vcurve" d="${pV}"/><path class="scurve" d="${pS}"/>
<line class="cursor" x1="${cx}" y1="8" x2="${cx}" y2="${CH - 22}"/><circle class="cdot" cx="${cx}" cy="${Y(p.s)}" r="3.5"/>
<text class="ct" x="${CW - 12}" y="18" text-anchor="end">s (mm) — solid · v — dashed</text></svg>`;
}

export function mount(root, env) {
  let st = M.initial(), raf = 0, last = 0, zoom = false, visible = true, W = 0;
  root.innerHTML = `<div class="cf">
<div class="cf-art"><svg id="cam-svg" class="iso" role="img" aria-label="Radial cam with roller follower in perspective"></svg></div>
<div class="cf-side">
<div class="cf-row"><button id="play" type="button">Play</button><button id="reset" type="button">Reset</button><button id="zoom" type="button" aria-pressed="false">Close-up: contact (optional)</button></div>
<label class="cf-l">Speed <output id="rpm-out">20 rpm</output><input id="speed" type="range" min="2" max="60" step="1" value="20"></label>
<label class="cf-l">Cam angle <output id="ang-out">0°</output><input id="angle" type="range" min="0" max="359" step="1" value="0"></label>
<div class="cf-row" role="group" aria-label="Displacement law">${Object.entries(M.LAWS).map(([key, n]) => `<button type="button" id="law-${key}" class="law">${n}</button>`).join('')}</div>
<div class="cf-row"><label class="cf-l inline">Lift h (mm) <input id="lift" type="number" min="6" max="40" step="1" value="16"></label><button id="apply-lift" type="button">Apply lift</button></div>
<div id="chart"></div>
<dl id="readout" class="cf-read"></dl>
<p id="status" class="cf-status" role="status" aria-live="polite"></p>
<details><summary>Parts &amp; idealizations</summary><p>Grey upright and pillow block carry the shaft and the guide arm; both bolt to the base plate. The accented disc is the cam; the roller turns on a pin in a fork, the stem slides in the bronze bushing and the coil spring pushes the collar down so the roller stays on the cam. Rigid parts, no friction or clearance; spring force is only k·compression, not a load rating.</p></details>
</div></div>`;
  const $ = (id) => root.querySelector('#' + id), svg = $('cam-svg');
  function frame() {
    const w = root.clientWidth || 600, narrow = w < 640;
    const VW = narrow ? 360 : 520, VH = narrow ? 420 : 520;
    const P = k.fitProjection(worldBounds(), VW, VH, { pad: 8, azimuth: 40, elevation: 24 });
    let vb = `0 0 ${VW} ${VH}`;
    if (zoom) { const c = k.iso(contactPoint(st), P); vb = `${(c[0] - 70).toFixed(1)} ${(c[1] - 70).toFixed(1)} 140 140`; }
    svg.setAttribute('viewBox', vb);
    svg.innerHTML = draw(st, P);
  }
  function ui() {
    const p = M.pose(st);
    frame();
    $('play').textContent = st.playing ? 'Pause' : 'Play';
    $('rpm-out').textContent = `${st.rpm} rpm`;
    $('ang-out').textContent = `${Math.round(p.deg)}°`;
    if (!st.playing) $('angle').value = String(Math.round(p.deg) % 360);
    root.querySelectorAll('.law').forEach((b) => b.setAttribute('aria-pressed', String(b.id === 'law-' + st.law)));
    $('chart').innerHTML = chart(st);
    $('readout').innerHTML = [['Phase', p.phase], ['Lift s', `${p.s.toFixed(2)} mm`], ['ds/dθ', `${p.v.toFixed(2)} mm/rad`], ['Pressure angle', `${p.pressure.toFixed(1)}°`], ['Spring', `${p.springL.toFixed(1)} mm · ${p.springF.toFixed(1)} N`], ['Law', M.LAWS[st.law]]].map(([a, b]) => `<div><dt>${a}</dt><dd>${b}</dd></div>`).join('');
    $('status').textContent = st.msg;
  }
  function tick(t) {
    raf = 0;
    if (!st.playing || !visible) return;
    const dt = last ? (t - last) / 1000 : 0; last = t;
    st = M.advance(st, dt); ui();
    raf = requestAnimationFrame(tick);
  }
  const start = () => { if (st.playing && visible && !raf) { last = 0; raf = requestAnimationFrame(tick); } };
  const stop = () => { if (raf) cancelAnimationFrame(raf); raf = 0; };
